# ----------------------------------------------------------------------
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None,
                 padding: int = 0, dilation: int = 1,
                 return_indices: bool = False):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices   # ignored – only values are produced

        # load PTX module using the harness utilities (assumed to be in the env)
        self._module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, C, L = x.shape
        # compute output length using the same formula as PyTorch
        out_len = (L + 2 * self.padding -
                   self.dilation * (self.kernel_size - 1) - 1) // self.stride + 1

        out = torch.empty((B, C, out_len), dtype=torch.float16,
                          device=x.device)

        # launch configuration: 128 threads per block along X,
        # one block per (batch,channel) slice along Y
        threads_per_block = (128, 1, 1)
        blocks_x = (out_len + 127) // 128
        blocks_y = B * C
        grid = (blocks_x, blocks_y, 1)

        args = [
            x.data_ptr(),
            out.data_ptr(),
            B,
            C,
            L,
            out_len,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation
        ]

        ptx_launch(self._module, "maxpool1d_fp16", grid, threads_per_block, args)

        return out
